# @@ the problem: y' = -2 t y, y(0) = 1, exact y = exp(-t^2)
def f(t, y) {
    return -2.0 * t * y
}
def exact(t) {
    return py_mexp(-t * t)
}
# @@ forward Euler
def euler(f, y0, t_end, n) {
    h = py_div_f(t_end, n)
    t = 0.0
    y = y0
    for _ to n {
        y += h * f(t, y)
        t += h
    }
    return y
}
# @@ the error halves when the step halves
T_END = 2.0
N0 = 10
REFINEMENTS = 5
errors = []
for k to REFINEMENTS {
    n = py_int(N0 * py_ipow(2, k))
    y = euler(f, 1.0, T_END, n)
    errors = append(errors, abs(y - exact(T_END)))
    print(fmt(n + 0.0, "4d"), "steps  y(2) =", fmt(y, ".9f"), " error =", fmt(errors[-1], ".3e"))
}
for k from 1 to REFINEMENTS {
    print("halving the step divides the error by", fmt(py_div_f(errors[py_int(k - 1)], errors[k]), ".3f"))
}
# @@ checks
if not (abs(py_div_f(errors[-2], errors[-1]) - 2.0) < 0.1) {
    stop("AssertionError")
}
